def render_holidays(soup, language):
    title, markets, concerts, details, intro, note, names, descriptions = COPY[language]

    def add(parent, tag, value=None, **attrs):
        node = soup.new_tag(tag, attrs=attrs)
        if value is not None:
            node.string = value
        parent.append(node)
        return node

    section = soup.new_tag('section', id=ANCHOR, attrs={'class': 'wrap holiday-guide'})
    header = add(section, 'div', **{'class': 'holiday-intro'})
    add(header, 'p', '2026 / 2027', **{'class': 'section-label'})
    add(header, 'h2', title)
    add(header, 'p', intro)
    regional_title, *regional_descriptions = REGIONAL_COPY[language]
    groups = (
        (markets, EVENTS[:4], names[:4], descriptions[:4]),
        (concerts, EVENTS[4:], names[4:], descriptions[4:]),
        (regional_title, REGIONAL_EVENTS, tuple(event[0].split(' · ')[0] for event in REGIONAL_EVENTS), regional_descriptions),
    )
    for heading, events, titles, summaries in groups:
        add(section, 'h3', heading)
        listing = add(section, 'ul', **{'class': 'holiday-list', 'role': 'list'})
        for (venue, start, end, url), name, description in zip(events, titles, summaries, strict=True):
            card = add(listing, 'li')
            date = add(card, 'p', **{'class': 'holiday-date'})
            add(date, 'time', start, datetime=start)
            if end != start:
                date.append(' – ')
                add(date, 'time', end, datetime=end)
            add(card, 'h4', name)
            add(card, 'p', venue)
            add(card, 'p', description)
            add(card, 'a', details, href=url, **{'aria-label': f'{details} · {name}'})
    add(section, 'p', note, **{'class': 'holiday-note'})
    return section
